known_examples.code:
state def StateDef1 {
    /* members */
}

state state1 : StateDef1 {
    entry action1;
    do action2;
    exit action3;
}

state compositeState1 {
    entry; then state1;
    state state1;
    transition first state1 accept trigger1 if guard1 do action1 then state2;
    state state2;
    then done;
}

state compositeState2 parallel {
    state state1 {
        entry; then 'state1.1';
        state 'state1.1';
    }
    state state2 {
        entry; then 'state2.1';
        state 'state2.1';
    }
}

state state1 : State1;
state state2 : State2;
transition first state1 accept trigger1 if guard1 do action1 then state2;

state def State1;
state state1 : State1;
part part1 {
    exhibit state1;
}

state def State1;
part part1 : Part1 {
    exhibit state state1 : State1;
}

state def Exercising {
    entry action warmup : WarmUp;
    do action exercise : Exercise {
        action strengthTraining;
        then action cardioTraining;
    }
    exit action cooldown : Cooldown;
}

state def Operating {
    entry assign stateCode := StateCodes::Operating;
    do send new ReadySignal() to Controller;
}

action monitorTemperature;
state def TurnedOn {
    entry;
    do monitorTemperature;
}

state def OperationalStates {
    entry action initial;
    then off;
    state off;
    state starting;
    state on;
}

state def OperationalStates {
    entry action initial { out attribute isStarting : Boolean; }
    if not initial.isStarting then off;
    if initial.isStarting then starting;
    state off;
    state starting;
    state on;
}

state def VehicleStates parallel {
    state OperationalStates;
    state HealthStates;
}

state def OnOff1 {
    entry;
    then off;
    state off;
    state on;
    transition off_on first off then on;
    transition on_off first on then off;
}

item def TurnOn;
state def OnOff2 {
    port commPort;
    entry;
    then off;
    state off;
    state on;
    transition off_on first off accept TurnOn via commPort then on;
    transition on_off first on accept after 5[min] then off;
}

state def OnOff3 {
    in attribute isInitOff : Boolean;
    in attribute isEnabled : Boolean;
    port commPort;
    entry action init;
    transition first init if isInitOff then off;
    transition first init if not isInitOff then on;
    state off;
    state on;
    transition off_on first off accept TurnOn via commPort if isEnabled then on;
    transition on_off first on accept after 5[min] if isEnabled then off;
}

action def PowerUp;
item def TimeoutSignal;
state def OnOff4 {
    in attribute isInitOff;
    in attribute isEnabled;
    port commPort;
    entry action init;
    transition first init if isInitOff then off;
    transition first init if not isInitOff then on;
    state off;
    state on;
    transition off_on first off if isEnabled accept TurnOn via commPort do action powerUp : PowerUp; then on;
    transition on_off first on if isEnabled accept after 5[min] do send new TimeoutSignal() via commPort then off;
}

action def PowerUp;
item def TimeoutSignal;
state def OnOff5 {
    in attribute isInitOff;
    in attribute isEnabled;
    port commPort;
    entry;
    if isInitOff then off;
    if not isInitOff then on;
    state off;
    accept TurnOn via commPort if isEnabled do action powerUp : PowerUp; then on;
    state on;
    accept after 5[min] if isEnabled do send new TimeoutSignal() via commPort; then off;
}

item def Abort;
state def OnOff6 {
    port commPort;
    entry; then off;
    state off;
    accept TurnOn via commPort then on;
    accept Abort via commPort then stop;
    state on;
    accept after 5[min] then done;
    action stop terminate;
}

part def Vehicle {
    exhibit state operatingState references VehicleStates::operating;
    abstract exhibit state monitoringState;
}

part vehicle : Vehicle {
    exhibit VehicleStates::monitoring :> Vehicle::monitoringState;
}
